package update

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// PromotionIndex is the strict input of PromoteRelease. It points at reports
// generated by actual BuildKit, scanner and test commands. LensDock only
// validates, copies and hashes them; it never manufactures attestations or
// marks tests passed.
type PromotionIndex struct {
	SchemaVersion int                              `json:"schemaVersion"`
	ReleaseID     string                           `json:"releaseId"`
	Images        map[string]PromotionArchEvidence `json:"images"`
	Tests         PromotionTests                   `json:"tests"`
}

type PromotionArchEvidence struct {
	Runtime PromotionImageEvidence  `json:"runtime"`
	Gateway *PromotionImageEvidence `json:"gateway,omitempty"`
}

type PromotionImageEvidence struct {
	// ManifestDigest is the platform image manifest digest. BuildKit's SBOM
	// and provenance attestations name it; ImageRef.Digest may name the OCI
	// index that also carries the attestations.
	ManifestDigest string `json:"manifestDigest"`
	SBOM           string `json:"sbom"`
	Provenance     string `json:"provenance"`
	Scan           string `json:"scan"`
	ScanTool       string `json:"scanTool"`
	// ScanToolVersion is the output of the scanner's version command.
	ScanToolVersion string    `json:"scanToolVersion"`
	ScannedAt       time.Time `json:"scannedAt"`
}

type PromotionTests struct {
	Report  string `json:"report"`
	Summary string `json:"summary"`
}

// ReleaseTestReport is the minimum report the promotion accepts. CI may add
// fields; passed must be true and releaseId exact.
type ReleaseTestReport struct {
	SchemaVersion int       `json:"schemaVersion"`
	ReleaseID     string    `json:"releaseId"`
	Passed        bool      `json:"passed"`
	StartedAt     time.Time `json:"startedAt"`
	FinishedAt    time.Time `json:"finishedAt"`
	Commands      []string  `json:"commands"`
	Platforms     []string  `json:"platforms"`
}

func loadPromotionIndex(path string) (PromotionIndex, error) {
	data, err := readFileLimit(path, 4<<20)
	if err != nil {
		return PromotionIndex{}, err
	}
	var idx PromotionIndex
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&idx); err != nil {
		return PromotionIndex{}, fmt.Errorf("decode promotion index: %w", err)
	}
	if err := ensureJSONEOF(dec); err != nil {
		return PromotionIndex{}, fmt.Errorf("decode promotion index: %w", err)
	}
	if idx.SchemaVersion != 1 {
		return PromotionIndex{}, errors.New("promotion index schemaVersion must be 1")
	}
	return idx, nil
}

func copyEvidence(outDir, rel, src string) (Attachment, error) {
	if err := validateRelPath(rel); err != nil {
		return Attachment{}, err
	}
	fi, err := os.Lstat(src)
	if err != nil {
		return Attachment{}, err
	}
	if !fi.Mode().IsRegular() {
		return Attachment{}, fmt.Errorf("%s is not a regular file", src)
	}
	in, err := os.Open(src)
	if err != nil {
		return Attachment{}, err
	}
	defer in.Close()
	path := filepath.Join(outDir, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return Attachment{}, err
	}
	out, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		return Attachment{}, err
	}
	h := sha256.New()
	n, cpErr := io.Copy(io.MultiWriter(out, h), io.LimitReader(in, maxEvidenceBytes+1))
	syncErr := out.Sync()
	closeErr := out.Close()
	if cpErr != nil {
		return Attachment{}, cpErr
	}
	if n > maxEvidenceBytes {
		return Attachment{}, fmt.Errorf("evidence %s is larger than %d bytes", src, int64(maxEvidenceBytes))
	}
	if syncErr != nil {
		return Attachment{}, syncErr
	}
	if closeErr != nil {
		return Attachment{}, closeErr
	}
	return Attachment{Path: rel, SHA256: hex.EncodeToString(h.Sum(nil)), Size: n}, nil
}

func readSBOMFormat(path string) (string, error) {
	data, err := readFileLimit(path, maxEvidenceBytes)
	if err != nil {
		return "", err
	}
	var doc struct {
		SPDXVersion string `json:"spdxVersion"`
		BOMFormat   string `json:"bomFormat"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		return "", fmt.Errorf("SBOM is not JSON: %w", err)
	}
	switch {
	case strings.HasPrefix(doc.SPDXVersion, "SPDX-"):
		return "spdx-json", checkSBOMDocument(path, "spdx-json")
	case doc.BOMFormat == "CycloneDX":
		return "cyclonedx-json", checkSBOMDocument(path, "cyclonedx-json")
	default:
		return "", errors.New("SBOM is neither SPDX JSON nor CycloneDX JSON")
	}
}

func readProvenance(path, subject string) (string, error) {
	data, err := readFileLimit(path, maxEvidenceBytes)
	if err != nil {
		return "", err
	}
	var st struct {
		PredicateType string `json:"predicateType"`
	}
	if err := json.Unmarshal(data, &st); err != nil {
		return "", fmt.Errorf("provenance is not JSON: %w", err)
	}
	if err := checkProvenanceStatement(path, st.PredicateType, subject); err != nil {
		return "", err
	}
	return st.PredicateType, nil
}

func trivySummary(path, subject string) (VulnSummary, error) {
	data, err := readFileLimit(path, maxEvidenceBytes)
	if err != nil {
		return VulnSummary{}, err
	}
	var report struct {
		SchemaVersion int    `json:"SchemaVersion"`
		ArtifactName  string `json:"ArtifactName"`
		Results       []struct {
			Vulnerabilities []struct {
				Severity string `json:"Severity"`
			} `json:"Vulnerabilities"`
		} `json:"Results"`
	}
	if err := json.Unmarshal(data, &report); err != nil {
		return VulnSummary{}, fmt.Errorf("scan report is not Trivy JSON: %w", err)
	}
	if report.SchemaVersion < 2 || report.ArtifactName == "" {
		return VulnSummary{}, errors.New("scan report has no Trivy SchemaVersion or ArtifactName")
	}
	if !strings.Contains(report.ArtifactName, subject) && !strings.Contains(report.ArtifactName, strings.TrimPrefix(subject, "sha256:")) {
		return VulnSummary{}, fmt.Errorf("scan ArtifactName %q is not bound to %s", report.ArtifactName, subject)
	}
	var s VulnSummary
	for _, result := range report.Results {
		for _, v := range result.Vulnerabilities {
			switch strings.ToUpper(v.Severity) {
			case "CRITICAL":
				s.Critical++
			case "HIGH":
				s.High++
			case "MEDIUM":
				s.Medium++
			case "LOW":
				s.Low++
			default:
				s.Unknown++
			}
		}
	}
	return s, nil
}

func loadTestReport(path, releaseID string) (ReleaseTestReport, error) {
	data, err := readFileLimit(path, maxEvidenceBytes)
	if err != nil {
		return ReleaseTestReport{}, err
	}
	var r ReleaseTestReport
	if err := json.Unmarshal(data, &r); err != nil {
		return r, fmt.Errorf("test report is not JSON: %w", err)
	}
	if r.SchemaVersion != 1 || r.ReleaseID != releaseID || !r.Passed || r.StartedAt.IsZero() || r.FinishedAt.IsZero() || len(r.Commands) == 0 || len(r.Platforms) == 0 {
		return r, errors.New("test report must have schemaVersion 1, the exact releaseId, passed=true, timestamps, commands and platforms")
	}
	return r, nil
}

// PromoteRelease copies a dev manifest's exact image/CLI/APT pins to a new
// release-channel manifest, attaching reports generated by BuildKit, Trivy and
// the acceptance run. It refuses dirty source, placeholders, missing evidence,
// failed tests and any provenance/scan that is not bound to the image digest.
func PromoteRelease(devDir, outputDir, indexFile string) (*Manifest, error) {
	raw, err := readFileLimit(filepath.Join(devDir, ManifestFileName), maxManifestBytes)
	if err != nil {
		return nil, err
	}
	m, err := DecodeManifest(raw)
	if err != nil {
		return nil, err
	}
	if m.Channel != ChannelDev {
		return nil, errors.New("promotion input must be a dev-channel manifest")
	}
	if m.Source.Dirty {
		return nil, errors.New("a manifest built from a dirty worktree cannot be promoted")
	}
	idx, err := loadPromotionIndex(indexFile)
	if err != nil {
		return nil, err
	}
	if idx.ReleaseID != m.ReleaseID {
		return nil, fmt.Errorf("promotion index releaseId %q differs from manifest %q", idx.ReleaseID, m.ReleaseID)
	}
	if _, err := loadTestReport(idx.Tests.Report, m.ReleaseID); err != nil {
		return nil, err
	}
	if strings.TrimSpace(idx.Tests.Summary) == "" {
		return nil, errors.New("promotion tests.summary is required")
	}
	if err := os.Mkdir(outputDir, 0o755); err != nil {
		return nil, fmt.Errorf("create release directory: %w", err)
	}
	removeOnError := true
	defer func() {
		if removeOnError {
			_ = os.RemoveAll(outputDir)
		}
	}()
	m.Channel = ChannelRelease
	for _, arch := range sortedArches(m.Images) {
		ev, ok := idx.Images[arch]
		if !ok {
			return nil, fmt.Errorf("promotion index has no evidence for %s", arch)
		}
		imgs := m.Images[arch]
		runtimeRef, err := promoteImage(outputDir, "runtime-"+arch, imgs.Runtime, ev.Runtime)
		if err != nil {
			return nil, err
		}
		imgs.Runtime = runtimeRef
		if imgs.Gateway != nil {
			if ev.Gateway == nil {
				return nil, fmt.Errorf("promotion index has no gateway evidence for %s", arch)
			}
			gw, err := promoteImage(outputDir, "gateway-"+arch, *imgs.Gateway, *ev.Gateway)
			if err != nil {
				return nil, err
			}
			imgs.Gateway = &gw
		} else if ev.Gateway != nil {
			return nil, fmt.Errorf("promotion index has gateway evidence for %s but the manifest has no gateway image", arch)
		}
		m.Images[arch] = imgs
	}
	att, err := copyEvidence(outputDir, "evidence/tests.json", idx.Tests.Report)
	if err != nil {
		return nil, err
	}
	m.Tests = &TestsEvidence{Attachment: att, Summary: idx.Tests.Summary, Passed: true}
	if err := m.Validate(); err != nil {
		return nil, err
	}
	if err := writeJSONAtomic(filepath.Join(outputDir, ManifestFileName), &m, 0o644); err != nil {
		return nil, err
	}
	removeOnError = false
	return &m, nil
}

func promoteImage(outDir, name string, ref ImageRef, ev PromotionImageEvidence) (ImageRef, error) {
	if ev.ScanTool != "trivy" || ev.ScanToolVersion == "" || ev.ScannedAt.IsZero() {
		return ref, fmt.Errorf("%s: scanTool must be trivy with version and scannedAt", name)
	}
	if !digestPattern.MatchString(ev.ManifestDigest) {
		return ref, fmt.Errorf("%s: manifestDigest must be sha256:<64 hex>", name)
	}
	ref.ManifestDigest = ev.ManifestDigest
	format, err := readSBOMFormat(ev.SBOM)
	if err != nil {
		return ref, fmt.Errorf("%s SBOM: %w", name, err)
	}
	predicate, err := readProvenance(ev.Provenance, ref.ManifestDigest)
	if err != nil {
		return ref, fmt.Errorf("%s provenance: %w", name, err)
	}
	summary, err := trivySummary(ev.Scan, ref.Digest)
	if err != nil {
		return ref, fmt.Errorf("%s scan: %w", name, err)
	}
	sbom, err := copyEvidence(outDir, "evidence/"+name+".sbom.json", ev.SBOM)
	if err != nil {
		return ref, err
	}
	sbom.SubjectDigest = ref.ManifestDigest
	provenance, err := copyEvidence(outDir, "evidence/"+name+".provenance.json", ev.Provenance)
	if err != nil {
		return ref, err
	}
	provenance.SubjectDigest = ref.ManifestDigest
	scan, err := copyEvidence(outDir, "evidence/"+name+".trivy.json", ev.Scan)
	if err != nil {
		return ref, err
	}
	scan.SubjectDigest = ref.Digest
	ref.SBOM = &SBOMEvidence{Attachment: sbom, Format: format, Generator: GeneratorBuildKit}
	ref.Provenance = &ProvenanceEvidence{Attachment: provenance, PredicateType: predicate, Generator: GeneratorBuildKit}
	ref.Scan = &ScanEvidence{Attachment: scan, Tool: ev.ScanTool, ToolVersion: ev.ScanToolVersion, ScannedAt: ev.ScannedAt, Summary: summary}
	return ref, nil
}

// sortedIndexArches is useful to release tooling that presents the index.
func sortedIndexArches(idx PromotionIndex) []string {
	out := make([]string, 0, len(idx.Images))
	for a := range idx.Images {
		out = append(out, a)
	}
	sort.Strings(out)
	return out
}
